draw:
var g = 9.8;
var L = 5.0, mp = 30, mper = p.mass, x = p.pos;
var Wp = mp * g, Wper = mper * g;
var NR = (Wp * (L / 2) + Wper * x) / L;
var NL = Wp + Wper - NR;

var x0 = W * 0.12, x1 = W * 0.88, by = H * 0.52;
function px(u) { return x0 + (u / L) * (x1 - x0); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function arrow(sx, sy, ex, ey, col) {
  var dx = ex - sx, dy = ey - sy, m = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / m, uy = dy / m;
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - ux * 10 - uy * 5, ey - uy * 10 + ux * 5);
  ctx.lineTo(ex - ux * 10 + uy * 5, ey - uy * 10 - ux * 5);
  ctx.closePath(); ctx.fill();
}

// plank
ctx.fillStyle = C.faint;
ctx.fillRect(x0, by - 7, x1 - x0, 14);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.strokeRect(x0, by - 7, x1 - x0, 14);

// supports as triangles
ctx.fillStyle = C.rule;
var sup = [px(0), px(L)];
for (var i = 0; i < 2; i++) {
  ctx.beginPath();
  ctx.moveTo(sup[i], by + 8);
  ctx.lineTo(sup[i] - 12, by + 28);
  ctx.lineTo(sup[i] + 12, by + 28);
  ctx.closePath(); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("A", px(0) - 4, by + 42);
ctx.fillText("B", px(L) - 4, by + 42);

// normal forces up
var sc = (H * 0.30) / 900;
arrow(px(0), by - 8, px(0), by - 8 - NL * sc, C.accent);
arrow(px(L), by - 8, px(L), by - 8 - NR * sc, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("N_A = " + NL.toFixed(0) + " N", px(0) - 14, by - 16 - NL * sc);
ctx.fillText("N_B = " + NR.toFixed(0) + " N", px(L) - 44, by - 16 - NR * sc);

// plank weight at centre
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px(L / 2), by, 4, 0, Math.PI * 2); ctx.fill();
arrow(px(L / 2), by + 8, px(L / 2), by + 8 + Wp * sc, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("plank " + Wp.toFixed(0) + " N at 2.5 m", px(L / 2) - 50, by + 24 + Wp * sc);

// person weight
arrow(px(x), by + 8, px(x), by + 8 + Wper * sc, C.figure);
ctx.fillText("person " + Wper.toFixed(0) + " N", px(x) - 34, by + 38 + Wper * sc);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(px(x), by - 40); ctx.lineTo(px(x), by - 8); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("x = " + x.toFixed(2) + " m", px(x) - 26, by - 46);

out.note = "N_A = " + NL.toFixed(1) + " N, N_B = " + NR.toFixed(1) + " N, total " + (NL + NR).toFixed(1) + " N";
